#include <array>
#include <cassert>
#include <iostream>
#include <stdexcept>
#include <string>
bool CanMatch(const std::string& cards, const std::string& target) {
    if (cards.size()>100000 || target.size()>100000) throw std::invalid_argument("length");
    std::array<int,26> count{}; int wild=0;
    // 유효성은 길이 비교보다 먼저 모두 확인합니다.
    for (unsigned char c:cards) { if(c=='?') ++wild; else if(c>='A'&&c<='Z') ++count[c-'A']; else throw std::invalid_argument("card"); }
    for (unsigned char c:target) if(c<'A'||c>'Z') throw std::invalid_argument("target");
    if(cards.size()!=target.size()) return false;
    for(unsigned char c:target) { int& left=count[c-'A']; if(left>0) --left; else if(wild>0) --wild; else return false; }
    return true;
}
int main(){
    assert(CanMatch("AA?C","ABCA")); assert(!CanMatch("AA?C","BBCA"));
    assert(CanMatch("??","ZZ")); assert(CanMatch("",""));
    assert(!CanMatch("A","AA"));
    bool rejected=false;try{CanMatch("!","A");}catch(const std::invalid_argument&){rejected=true;}assert(rejected);
    std::cout << "wildcard checks passed\n";
}
